# The slow way: ~50x slower than vectorized ops on 1M rows
for idx, row in df.iterrows():
    df.at[idx, 'total'] = row['price'] * row['quantity']

# Same loop, far less overhead
for row in df.itertuples():
    process(row.price, row.quantity)  # access via attribute names

def score_row(row):
    return row['price'] * row['quantity'] * (1 - row['discount'])

df['final'] = df.apply(score_row, axis=1)
